import sys

def main():
    lines = sys.stdin.read().split()
    if not lines:
        return
    s = lines[0]
    max_len = 1
    curr_len = 1
    for i in range(1, len(s)):
        diff = ord(s[i]) - ord(s[i-1])
        if diff == 0 or diff == 1:
            curr_len += 1
        else:
            curr_len = 1
        max_len = max(max_len, curr_len)
    print(max_len)

if __name__ == '__main__':
    main()
